local _rawDecoded do
 local alphabet="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
 local map={}
 for i=1,#alphabet do map[alphabet:sub(i,i)]=i-1 end
 local t={}; local acc,bits=0,0
 for i=1,#_raw do
  local c=_raw:sub(i,i)
  if c~="=" and c~="\n" and c~="\r" and c~=" " and c~="\t" then
   local v=map[c]; if v==nil then error("Invalid payload") end
   acc=acc*64+v; bits=bits+6
   if bits>=8 then bits=bits-8; t[#t+1]=string.char(math.floor(acc/2^bits)%256); acc=acc%2^bits end
  end
 end
 _rawDecoded=table.concat(t)
end
local _plain=_chacha(_kf,_nf,_rawDecoded)
local _run=loadstring or load
assert(type(_run)=="function","loadstring/load is not supported")
local _fn,_err=_run(_plain,"APEX_PROTECTED")
assert(type(_fn)=="function",_err or "Decrypted payload is invalid")
return _fn()
